syntax:
template <typename T>
// General template
void func(T arg) { /* generic implementation */ }

// Full specialization for a specific type
template <> 
void func(int arg) { /* specialized implementation for int */ }

// SFINAE with enable_if to conditionally enable templates
#include <type_traits>
template <typename T>
typename std::enable_if<std::is_integral<T>::value>::type
func(T arg) { /* enabled only for integral types */ }

code_example:
#include <iostream>
#include <type_traits>

// Generic template function
template <typename T>
void process(T value) {
    std::cout << "Processing generic type: " << value << std::endl;
}

// Specialization for int type
template <>
void process(int value) {
    std::cout << "Processing int: " << value << std::endl;
}

// SFINAE: enable only for integral types
template <typename T>
typename std::enable_if<std::is_integral<T>::value>::type
process(T value) {
    std::cout << "Processing integral type: " << value << std::endl;
}

int main() {
    process(42);          // Calls specialized for int and enabled by SFINAE
    process(3.14);        // Calls generic template (double)
    process("hello");   // Calls generic template (const char*)
    return 0;
}
